"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["3500"],{1685(e,t,o){o.r(t),o.d(t,{metadata:()=>n,default:()=>u,frontMatter:()=>i,contentTitle:()=>s,toc:()=>d,assets:()=>c});var n=JSON.parse('{"id":"reference/monitor/howtos/HowToUpgradeToALEOS_470","title":"How to upgrade to ALEOS 4.7.0 (LWM2M)","description":"alms \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/reference/monitor/howtos/HowToUpgradeToALEOS_470.md","sourceDirName":"reference/monitor/howtos","slug":"/reference/monitor/howtos/HowToUpgradeToALEOS_470","permalink":"/personal-av-docs/docs/reference/monitor/howtos/HowToUpgradeToALEOS_470","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/reference/monitor/howtos/HowToUpgradeToALEOS_470.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"How to upgrade to ALEOS 4.7.0 (LWM2M)","sidebar_label":"How to upgrade to ALEOS 4.7.0 (LWM2M)","sidebar_position":99,"edition":"alms","source":"https://doc.airvantage.net/alms/reference/monitor/howtos/HowToUpgradeToALEOS_470","format":"md"}}'),r=o(4848),a=o(8453);let i={title:"How to upgrade to ALEOS 4.7.0 (LWM2M)",sidebar_label:"How to upgrade to ALEOS 4.7.0 (LWM2M)",sidebar_position:99,edition:"alms",source:"https://doc.airvantage.net/alms/reference/monitor/howtos/HowToUpgradeToALEOS_470",format:"md"},s,c={},d=[];function l(e){let t={a:"a",p:"p",strong:"strong",...(0,a.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsxs)(t.p,{children:[":::note Edition\n",(0,r.jsx)(t.strong,{children:"alms"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,r.jsx)(t.a,{href:"https://doc.airvantage.net/alms/reference/monitor/howtos/HowToUpgradeToALEOS_470",children:"Original page"}),".\n:::"]}),"\n",(0,r.jsx)(t.p,{children:"How to upgrade to ALEOS 4.7.0 (LWM2M)\nWith the release of ALEOS 4.7.0 we are introducing a new protocol, Lightweight M2M (LWM2M), which manages the communications between AirLink gateways and ALMS. This change from MSCI (our legacy protocol) to LWM2M brings a number of benefits, which are outlined in a Technical Bulletin that you can access on\nthe Source\n.\nAs an ALMS user that has RV50, GX450 and/or ES450 devices in your account, we wanted to make sure you are aware of the implications of the upgrade to LWM2M, and are familiar with some of the changes that may be required to your infrastructure prior to upgrading. We suggest you take the following steps when upgrading to LWM2M.\nIn case of devices in a private APN, update your firewall rules\nAllow LWM2M to communicate both outbound toward the ALMS IP addresses, and inbound from ALMS IP addresses on ports\nUDP/5684\nand\nUDP/5686\n.\nUse ALMS to upgrade your devices to ALEOS 4.7.0.\nOur recommendation is that you either perform the upgrade locally from ACEmanager or from ALMS\nwith HTTPS enabled\n(ensure the Server URL under Services/ALMS/ is using HTTPS, not HTTP).\nVerify that your devices have switched to LWM2M\nWhen upgrading, the default communication protocol for ALMS switches from\n\u201CMSCI\u201D\nto\n\u201CLWM2M with fallback to MSCI\u201D\n. If the device can communicate over LWM2M it will continue to use the new protocol. If it cannot (e.g. firewall rules prevent communication), it will fall back to MSCI until the next time the device is rebooted, and will try again on LWM2M.\nYou can see if the protocol has changed in the \u201CFirmware\u201D column in the main\nMonitor -> System\ngrid. Devices running the MSCI version of the firmware will display, as an example, \u201CALEOS RV50 MSCI (4.7.0)\u201D. Devices running the LWM2M version of the firmware will display \u201CALEOS RV50 (4.7.0)\u201C.\nImportant Note:\nAs part of the release of ALEOS 4.7.0 we have created versions of your\nTemplates\n,\nDatasets\nand\nAlert Rules\nbased on the LWM2M version of the firmware.\nIf you collect periodic custom Dataset data, update \u201CConfigure communications\u201D to collect the correct data.\nMake sure to reset all fields \u2013 Heartbeat, Default Status Report, and Additional Datasets.\nThe LWM2M version of your Datasets have been created for you.\nReview Alert Rules\nThe LWM2M version of your Alert Rules have been created for you.\nAny Alert Rules you have created will be updated and automatically applied.\nYou should not need to do anything for Alerts to continue to operate normally.\nReview Templates\nWhen you upgrade from the previous firmware release to ALEOS 4.7.0, all of your configuration will be maintained, so there is nothing you need to do with your Templates to ensure your devices will continue to operate as expected.\nThe LWM2M version of your Templates have been created for you, and you can apply these new Templates when you register new devices. The current name will be maintained.\nUpdate Widgets\nAny widgets in ALMS that required configuration to select specific data values will need to be updated.\nThis includes Combo Charts, Data History Tables, Gauge Charts, Heat Maps, and Single value charts. Standard widgets that do not require configuration are unaffected.\nIf you need assistance with this process, please contact your\nAuthorized Sierra Wireless Partner\n. You can access their information in ALMS from the\nSupport\ntab in\nMy Account\n."})]})}function u(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,r.jsx)(t,{...e,children:(0,r.jsx)(l,{...e})}):l(e)}},8453(e,t,o){o.d(t,{R:()=>i,x:()=>s});var n=o(6540);let r={},a=n.createContext(r);function i(e){let t=n.useContext(a);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:i(e.components),n.createElement(a.Provider,{value:t},e.children)}}}]);